package com.codeguardian.service; import com.codeguardian.entity.*; import com.codeguardian.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class ReportService{private final ReviewTaskRepository tasks;private final FindingRepository findings;private final ReviewReportRepository reports;public String generateHTMLReport(Long id){ReviewTask t=tasks.findById(id).orElseThrow(()->new IllegalArgumentException("Task not found: "+id));String html=generate(t,findings.findByTaskId(id));ReviewReport r=reports.findByTaskId(id).orElseGet(()->ReviewReport.builder().task(t).build());r.setHtmlContent(html);r.setMarkdownContent("# CodeGuardian Review Report\n\nTask: "+t.getName());reports.save(r);return html;}public org.springframework.data.domain.Page<ReviewReport> history(org.springframework.data.domain.Pageable page){return reports.findAll(page);}private String generate(ReviewTask t,List<Finding> fs){int c=count(fs,"CRITICAL"),h=count(fs,"HIGH"),m=count(fs,"MEDIUM"),l=count(fs,"LOW");StringBuilder x=new StringBuilder("<!doctype html><html><head><meta charset='UTF-8'><title>CodeGuardian Report</title><style>body{font:14px system-ui;background:#0d1117;color:#c9d1d9;padding:32px}section{background:#161b22;border:1px solid #30363d;border-radius:8px;padding:20px;margin:16px 0}.stats{display:flex;gap:12px}.stat{padding:12px 18px;border-radius:6px;background:#21262d}.critical{color:#f85149}.high{color:#ff7b72}.medium{color:#d29922}.low{color:#3fb950}pre{white-space:pre-wrap;background:#0d1117;padding:16px;border-radius:6px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #30363d}</style></head><body><h1>CodeGuardian AI Review Report</h1><p>Task: ").append(esc(t.getName())).append("</p><section class='stats'><div class='stat critical'>Critical: ").append(c).append("</div><div class='stat high'>High: ").append(h).append("</div><div class='stat medium'>Medium: ").append(m).append("</div><div class='stat low'>Low: ").append(l).append("</div></section><section><h2>Code sample</h2><pre>").append(esc(t.getScope())).append("</pre></section><section><h2>Findings</h2><table><tr><th>Severity</th><th>Title</th><th>Location</th><th>Description</th><th>Suggestion</th></tr>");for(Finding f:fs)x.append("<tr><td class='").append(String.valueOf(f.getSeverity()).toLowerCase()).append("'>").append(esc(f.getSeverity())).append("</td><td>").append(esc(f.getTitle())).append("</td><td>").append(esc(f.getLocation())).append("</td><td>").append(esc(f.getDescription())).append("</td><td>").append(esc(f.getSuggestion())).append("</td></tr>");return x.append("</table></section></body></html>").toString();}private int count(List<Finding> f,String s){return (int)f.stream().filter(x->s.equalsIgnoreCase(x.getSeverity())).count();}private String esc(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}}
